(7007968, 1060603, 124982, '<td valign="top">Nicely executed. I had considered something like this, but never knew how to pull if off without crystal brown sugar.</td>', 'Nicely executed. I had considered something like this, but never knew how to pull if off without crystal brown sugar.', '2013-03-27 17:57:33.000000', NULL, 1),
(7007969, 1060580, 124982, '<td valign="top">Quite decadent! I''d love to take a big mouthful (or three) of that tart! Critically speaking, it''s a little out of focus..note how soft the strawberries are? If the DoF was deeper, this would have so much more impact.</td>', 'Quite decadent! I''d love to take a big mouthful (or three) of that tart! Critically speaking, it''s a little out of focus..note how soft the strawberries are? If the DoF was deeper, this would have so much more impact.', '2013-03-27 17:58:48.000000', NULL, 1),
